<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model;
class Project extends Model { protected $fillable=['name','description','status','priority','progress','auto_progress','archived','client','technology','environment','local_path','repository_url','started_at','next_step','notes']; protected $casts=['progress'=>'integer','auto_progress'=>'boolean','archived'=>'boolean','started_at'=>'date']; public function credentials(){return $this->hasMany(Credential::class);} public function urls(){return $this->hasMany(ResourceUrl::class);} public function plans(){return $this->hasMany(Plan::class);} public function progressLogs(){return $this->hasMany(ProjectProgressLog::class);} public function recalculateProgress():void{if(!$this->auto_progress)return;$plans=$this->plans()->where('type','HITO')->where('status','!=','CANCELADO')->get();if($plans->isEmpty())return;$total=$plans->sum('weight');$done=$plans->where('status','COMPLETADO')->sum('weight');$new=$total?min(100,(int)round($done/$total*100)):0;if($new!==$this->progress){$this->updateQuietly(['progress'=>$new]);$this->progressLogs()->create(['progress'=>$new,'source'=>'AUTO']);}} }
